insert into public.content_items(id,kind,payload,content_hash) values
('adhkar-waking','lesson','{"answer":0,"grade":"TODO_REVIEW","id":"adhkar-waking","meaning_older":"حين تصحو تشكر الله على يوم جديد أعطاك إياه. وفي الذكر معنى أبعد: كما أيقظك اليوم بعد نومك، يبعث الناس يوم القيامة بعد موتهم — فالرجوع إليه في الحالين.","meaning_young":"أول ما تستيقظ من النوم، تشكر الله. أنت كنت نائماً لا تعرف شيئاً عن الدنيا، ثم فتحت عينيك من جديد — وهذه نعمة من الله.","options":["لأنه أعطانا يوماً جديداً نعيشه","لأن النوم كان مريحاً","لأن الصباح جميل"],"pack":"adhkar","pose":"standing","question":"لماذا نشكر الله حين نستيقظ؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"morning","situation":"الاستيقاظ","source":"TODO_REVIEW","text":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَمَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ"}'::jsonb,'8c7a4eb85ecef64478dbc4176af2cf2364caa5e6da8080b3eacd8653d945219a'),
('adhkar-dressing','lesson','{"answer":0,"grade":"TODO_REVIEW","id":"adhkar-dressing","meaning_older":"تشكر الله على ثوب يسترك ويدفئك. وتتذكر أنك لم تحصل عليه بقوتك وحدك: الله هو الذي يسّره لك ورزقك إياه، وغيرك قد لا يجد مثله.","meaning_young":"حين تلبس ثوبك تشكر الله. فهو الذي أعطاك إياه، وأنت لم تصنعه بنفسك.","options":["أن الله هو الذي رزقنا إياه","أن الثوب غالي الثمن","أن لوننا المفضل جميل"],"pack":"adhkar","pose":"standing","question":"ماذا نتذكّر حين نلبس ثوبنا؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"home","situation":"لبس الثياب","source":"TODO_REVIEW","text":"الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّة"}'::jsonb,'bdc096916654a5edd267a7b385078d0789d4304ae2663bc003d46b35b33c481f'),
('adhkar-food-before','lesson','{"answer":0,"grade":"TODO_REVIEW","id":"adhkar-food-before","meaning_older":"قبل الطعام تطلب من الله أن يبارك لك فيه: أن يكون نافعاً لجسمك ومعيناً لك على الخير. وتطلب منه أن ينجّيك ويحفظك. ثم تبدأ أكلك ذاكراً اسم من رزقك إياه.","meaning_young":"قبل أن تأكل، تسأل الله أن يجعل طعامك خيراً لك. وتطلب منه أن يحفظك ويحميك، ثم تبدأ أكلك ذاكراً اسمه.","options":["أن يجعل الطعام خيراً ونافعاً لنا","أن يكون الطعام لذيذاً","أن نأكل كثيراً"],"pack":"adhkar","pose":"sitting","question":"ماذا نطلب من الله قبل الطعام؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"food","situation":"الطعام","source":"TODO_REVIEW","text":"اللَّهُمَّ بَارِكْ لَنَا فِيمَا رَزَقْتَنَا، وَقِنَا عَذَابَ النَّارِ، بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ"}'::jsonb,'d82b6415f16dabfb6bfb5863537e53f778af111e99e837d2a2845b90b5f1a244'),
('adhkar-food-after','lesson','{"answer":0,"grade":"TODO_REVIEW","id":"adhkar-food-after","meaning_older":"بعد الطعام تشكر الله على نعمتين: نعمة الطعام والشراب التي يحتاجها جسمك، ونعمة الهداية إلى دينه وهي أعظم منهما. فالذكر يذكّرك أن أكبر ما أُعطيت ليس ما في الصحن.","meaning_young":"بعد أن تأكل وتشرب، تشكر الله على طعامك وعلى الماء. وتشكره على نعمة أكبر منهما: أن هداك إلى دينه.","options":["نعمة أن جعلنا مسلمين","نعمة الأصدقاء","نعمة البيت"],"pack":"adhkar","pose":"sitting","question":"على أي نعمة نشكر الله في هذا الذكر غير الطعام والشراب؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"food","situation":"الطعام","source":"TODO_REVIEW","text":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ"}'::jsonb,'7c83c424b8ee78a671671eee9bb500e18e0eaf7db751c985d15e323c0f9bcdaa')
